candidates.raw:
    if ((a == NULL) || (b == NULL) || (angle_rad == NULL)) {
        return ADCS_E_NULL;
    }

    if (!adcs_is_finite_vec3(a) || !adcs_is_finite_vec3(b)) {
        *angle_rad = 0.0;
        return ADCS_E_NOT_FINITE;
    }

    double norm_a = adcs_vec3_norm(a);
    double norm_b = adcs_vec3_norm(b);

    if (norm_a <= ADCS_EPS_NORM || norm_b <= ADCS_EPS_NORM) {
        *angle_rad = 0.0;
        return ADCS_E_DEGENERATE;
    }

    adcs_vec3_t cross = adcs_vec3_cross(a, b);
    double dot_ab = adcs_vec3_dot(a, b);
    double cross_norm = adcs_vec3_norm(&cross);

    *angle_rad = atan2(cross_norm, dot_ab);

    return ADCS_OK;
}

